import { useState } from "react";

export function App() {
  const [count, setCount] = useState(0);
  return (
    <div>
      <button
        data-testid="stale-closure"
        onClick={() => {
          setTimeout(() => setCount(count), 10);
        }}
      >
        Stale closure state update
      </button>
      <span data-testid="status">count:{count}</span>
    </div>
  );
}

